import collections
def comps3(g, bg):
    seen=set(); res=collections.defaultdict(list)
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            if (i,j) in seen or g[i][j]==bg: continue
            c=g[i][j]; stack=[(i,j)]; cells=[]
            while stack:
                y,x=stack.pop()
                if (y,x) in seen or not(0<=y<H and 0<=x<W) or g[y][x]!=c: continue
                seen.add((y,x)); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        stack.append((y+dy,x+dx))
            if cells: res[c].append(cells)
    return res
