def bbox(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    return (min(ys),min(xs),max(ys),max(xs))
def cdist(a,b):
    ay,ax,by,bx=bbox(a); cy,cx,dy,dx=bbox(b)
    dy_=max(0,max(ay,cy)-min(by,dy)); dx_=max(0,max(ax,cx)-min(bx,dx))
    return (dy_**2+dx_**2)**0.5
