def quadrant(cells, cy, cx):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    my=sum(ys)/len(ys); mx=sum(xs)/len(xs)
    return ('U' if my<cy else 'D') + ('L' if mx<cx else 'R')
